[2932] = { en = "Grim Message", tier = 3,
  t = "Grimmige boodschap",
  d = "De Witherbark-trollen waren ooit bondgenoten van de Horde, maar ze hebben Thrall verraden... en daarvoor moeten ze gestraft worden!$B$BHier, neem mijn spies en ga naar de Hinterlands, ver in het noorden. Je vindt het ten noordoosten van Tarren Mill, een dorp van onze bondgenoten, de Forsaken.$B$BAls je in de Hinterlands komt, jaag dan op Witherbark-trollen. Verzamel hun schedels en steek mijn spies in de grond bij een van hun kleinere dorpen, Hiri'watha of Zun'watha.$B$BLaat ze zien dat hun gemene daden gevolgen hebben!",
  o = "Verzamel Witherbark Skulls en zet ze op Nimboya's Pike. Zet Nimboya's Laden Pike neer bij een van de Witherbark-dorpen in de Hinterlands en ga dan terug naar Nimboya in Stranglethorn.",
  p = "Je hebt mijn opdracht nog niet uitgevoerd, $N.",
  c = "Ik heb gehoord wat je hebt gedaan. Het was een grimmige daad, maar wel een daad van eer. Laten we hopen dat de Witherbarks je boodschap begrijpen.",
  e = "Zet de grimmige boodschap neer.",
  g = { {"grimmige", "grim (grimmig)"}, {"boodschap", "message"}, {"bondgenoten", "allies (bondgenoot)"}, {"verraden", "betrayed (verraden)"}, {"gestraft", "punished (straffen)"}, {"spies", "pike, spear"}, {"schedels", "skulls (schedel)"}, {"gemene", "vile, mean (gemeen)"}, {"daden", "deeds, actions (daad)"}, {"gevolgen", "consequences (gevolg)"}, {"eer", "honour"} },
