[7068] = { en = "Shadowshard Fragments", tier = 3,
  t = "Shadowshard-scherven",
  d = "Sterke magie zit in de heilige plek van de centauren... de heilige plek Maraudon. De centaurstammen van Desolace beschermen die plek met hun leven, maar ze kunnen ons niet tegenhouden als wij pakken wat we nodig hebben.$B$BJij, jij gaat naar die Maraudon-plek en zoekt de stenen wezens die van shadowshard zijn gemaakt. Jij brengt mij de paarse kristallen, en Uthel'nay maakt iets voor jou, voor je moeite.$B$BDe plek is gevaarlijk, dus misschien neem je wat vrienden mee.",
  o = "Verzamel 10 Shadowshard Fragments in Maraudon en breng ze terug naar Uthel'nay in Orgrimmar.",
  p = "Heb je de kristallen al gevonden? Rituelen van macht, spreuken van grote kracht... die shadowshards zijn misschien heel nuttig voor allerlei geheime magie.",
  c = "Ah, deze zijn perfect voor mijn magie. Hier, neem jij een van deze sieraden en ga maar verder... ik heb veel te bestuderen.",
  g = { {"heilige", "holy, sacred (heilig)"}, {"centauren", "centaurs (centaur)"}, {"centaurstammen", "centaur tribes (centaurstam)"}, {"tegenhouden", "to stop"}, {"paarse", "purple (paars)"}, {"kristallen", "crystals (kristal)"}, {"moeite", "trouble, effort"}, {"rituelen", "rituals (ritueel)"}, {"spreuken", "spells (spreuk)"}, {"nuttig", "useful"}, {"allerlei", "all kinds of"}, {"sieraden", "trinkets, jewellery (sieraad)"}, {"bestuderen", "to study"} },
},

[2933] = { en = "Venom Bottles", tier = 3,
  t = "Gifflessen",
  d = "In deze flessen zit een smerig, groen gif.$B$BEr staan veel flessen in dit dorp, dus de Witherbarks vinden het vast heel belangrijk. Misschien wil een apotheker in het nabije Tarren Mill wel een monster hebben.",
  o = "Breng een Venom Bottle naar een apotheker in Tarren Mill.",
  p = "Hallo, beste $c. Het was een lange dag, en geen enkel experiment is gelukt... Ik hoop dat je goed nieuws voor me hebt.",
  c = "Ah, en wat is dit? Het lijkt wel gif... van een of ander spinachtig wezen, denk ik. En waar heb je het vandaan?",
  g = { {"smerig", "vile, filthy"}, {"gif", "venom, poison"}, {"vast", "surely, no doubt"}, {"apotheker", "apothecary"}, {"nabije", "nearby (nabij)"}, {"monster", "sample"}, {"geen enkel", "not a single"}, {"spinachtig", "spider-like, arachnid"} },
