[1444] = { en = "Return to Fel'Zerul", tier = 3,
  t = "Terug naar Fel'Zerul",
  d = "Jammal'an de Profeet heeft me verbannen uit The Temple of Atal'Hakkar. Ooit vond ik de hogepriester een goede leider.$b$bMaar zijn onwrikbare geloof in zijn profetie zal de Atal'ai vernietigen. Als dat al niet gebeurd is.$b$bToen ik zei dat ik me zorgen maakte, werd ik een ongelovige genoemd en uit de tempel gezet.$b$bDie voorwerpen die je me bracht, zijn onschadelijk. Maar als Jammal'an de juiste betovering voor de fetisj voor het oproepingsritueel heeft gevonden, dan is de wereld in groot gevaar...",
  o = "Ga terug naar Fel'Zerul in Stonard.",
  c = "Het is al een tijd geleden dat we elkaar spraken, $c. Ik hoop dat je reis succesvol was.$b$bWat heb je te weten gekomen van de verbannen Atal'ai in de Hinterlands?",
  g = { {"profeet", "prophet"}, {"verbannen", "exiled, banished (verbannen)"}, {"hogepriester", "high priest"}, {"onwrikbare", "unshakable, unyielding (onwrikbaar)"}, {"profetie", "prophecy"}, {"vernietigen", "to destroy"}, {"ongelovige", "unbeliever, infidel"}, {"onschadelijk", "harmless"}, {"betovering", "enchantment, spell"}, {"fetisj", "fetish (magic object)"}, {"oproepingsritueel", "summoning ritual"} },
},

[2934] = { en = "Undamaged Venom Sac", tier = 3,
  t = "Onbeschadigde gifzak",
  d = "Ik moet een vers monster hebben van het gif dat je me bracht. De spinnen waar het vandaan komt, wonen vast in de Hinterlands. Jaag op ze tot je een onbeschadigde gifzak vindt, en breng die naar mij. Je vindt veel spinnen bij de trollenstad Shadra'Alor.$B$BTreuzel niet, $N, want de gifzak moet vers zijn als je hem brengt.",
  o = "Breng een Undamaged Venom Sac naar Apothecary Lydon in Tarren Mill.",
  p = "Heb je de onbeschadigde gifzak, $N? Ik verlang ernaar om experimenten te doen met het verse gif. Ik heb zelfs al een hele groep kleine, vreselijk schattige diertjes besteld om het op te testen!",
  c = "O, prachtig! Het gif is heel vers, en ik weet zeker dat het erg dodelijk is. Dank je!",
  g = { {"onbeschadigde", "undamaged (onbeschadigd)"}, {"gifzak", "venom sac"}, {"vers", "fresh"}, {"monster", "sample"}, {"trollenstad", "troll city"}, {"treuzel", "dawdle, tarry (treuzelen)"}, {"verlang ernaar", "long to, yearn (verlangen naar)"}, {"vreselijk", "terribly"}, {"schattige", "cute (schattig)"}, {"besteld", "ordered (bestellen)"}, {"dodelijk", "deadly"} },
},

[2935] = { en = "Consult Master Gadrin", tier = 3,
  t = "Raadpleeg Master Gadrin",
  d = "Het gif van de broodguards was niet zo sterk als het gif dat je eerst bracht. Het moet van een andere spin komen.$B$BIk wil een vers monster van dat gif. Om te ontdekken waar het vandaan komt, moet je een trol raadplegen die de Witherbarks goed kent: Master Gadrin in Sen'jin Village. Reis naar Durotar en spreek met Gadrin. Met wat geluk weet hij waar de Witherbarks hun gif vandaan halen.",
  o = "Spreek met Master Gadrin in Sen'jin Village.",
  c = "Ah, dus je wilt vers gif van de spin van de Witherbarks, ja? Nou, ga maar zitten... wat ik je ga vertellen, zal je niet bevallen.",
  g = { {"raadpleeg", "consult (raadplegen)"}, {"raadplegen", "to consult"}, {"gif", "venom"}, {"monster", "sample"}, {"ontdekken", "to find out"}, {"met wat geluk", "with luck"}, {"bevallen", "to please, be to one's liking"} },
},

[7730] = { en = "Zukk'ash Infestation", tier = 3,
  t = "Zukk'ash-plaag",
  d = "Onze verkenners hebben niet veel kunnen ontdekken. Toch denken we dat de vijand ten zuiden van de gnolls een soort insectenvolk is. Eerlijk gezegd maakt het niet uit of ze kunnen denken of niet. Als zij de gnolls zo razend tegen ons opzetten, dan zijn ze net zo'n grote bedreiging als de gnolls. Misschien zelfs een grotere.$B$BGa diep naar binnen in de plek waar deze Zukk'ash-insecten wonen; die heet de Writhing Deep. Dun hun aantal uit en vertel me wat je daar vindt. Breng hun schilden mee als bewijs van je werk.",
  o = "Breng 20 Zukk'ash Carapaces naar Hadoken Swiftstrider in Camp Mojache, Feralas.",
  p = "Hoe gaat de jacht, $N? Kom je me vertellen dat het gelukt is?",
  c = "Goed gedaan, $c. De Zukk'ash zijn zo talrijk dat alleen een volledige aanval ze echt kan tegenhouden. Maar jij hebt ons wat tijd gegeven, zodat we een goed plan kunnen bedenken.$B$BIk zorg dat deze schilden onderzocht worden. We moeten alles over ze te weten komen voordat we het aanpakken. Helaas is dit een veel groter probleem geworden dan we hadden verwacht.",
  g = { {"plaag", "infestation, plague"}, {"verkenners", "scouts (verkenner)"}, {"insectenvolk", "insect race"}, {"razend", "frenzied, furious"}, {"opzetten", "to set (someone) against (tegen iemand opzetten)"}, {"bedreiging", "threat"}, {"dun", "thin out (uitdunnen)"}, {"schilden", "shells, carapaces (schild)"}, {"bewijs", "proof, evidence"}, {"talrijk", "numerous"}, {"tegenhouden", "to stop, hold back"}, {"onderzocht", "examined, analyzed (onderzoeken)"}, {"aanpakken", "to deal with, tackle"}, {"verwacht", "expected (verwachten)"} },
},

[2822] = { en = "The Mark of Quality", tier = 4,
  t = "Het kenmerk van kwaliteit",
  d = "Ik ben trots op mijn leerwerk, en ik vind dat je dat ziet. Aan kwaliteit mag je nooit toegeven. Wie zegt dat kwaliteit niet belangrijk is, wil je ook laten geloven dat de aarde geen geheimen bewaart!$B$BOp zoek naar materiaal van hoge kwaliteit heb ik onlangs dikke yetihuiden ontdekt. Yeti's komen uit Feralas; je vindt ze vaak ten westen van hier, in Feral Scar Vale. Voor een stapel van tien mag je een van mijn leren spullen uitkiezen. Als je dat goed vindt, hebben we een afspraak!",
  o = "Breng 10 Thick Yeti Hides naar Jangdor Swiftstrider in Camp Mojache.",
  p = "Heb je een stapel van tien dikke yetihuiden kunnen vinden? Mijn leren spullen zijn de beste die er zijn, en ik geef je er wat van als je de huiden hebt.$B$BKun je geen yeti's vinden? Ik weet waar ze misschien zitten. Kijk ten westen van hier, net landinwaarts van de Forgotten Coast, rond Feral Scar Vale.",
  c = "Ah, uitstekend! Als deze huiden een speciale behandeling krijgen, zijn ze zo sterk als ijzer, echt waar! Het zal veel pogingen kosten om het juiste mengsel voor het looien te vinden. Maar ik weet zeker dat mijn kwaliteit er een stuk beter van wordt.$B$BEn jij, $n... jouw hulp is voor mij heel waardevol gebleken. Kies maar iets uit van deze spullen die ik heb gemaakt.",
  g = { {"kenmerk", "mark, sign"}, {"leerwerk", "leather work"}, {"toegeven", "to give in, compromise"}, {"bewaart", "keeps (bewaren)"}, {"onlangs", "recently"}, {"yetihuiden", "yeti hides (yetihuid)"}, {"stapel", "stack"}, {"uitkiezen", "to choose, pick out"}, {"landinwaarts", "inland"}, {"behandeling", "treatment"}, {"pogingen", "attempts, tries (poging)"}, {"mengsel", "mix, mixture"}, {"looien", "tanning (leather)"}, {"waardevol", "valuable"} },
},

[2979] = { en = "Dark Ceremony", tier = 4,
  t = "Duistere ceremonie",
  d = "Dit lijken plannen voor een soort duistere ceremonie, $N. Voor zover ik het kan lezen, wordt dit ritueel geleid door de Gordunni-magiërheren.$B$BZoek een van die magiërheren en pak een bol van hem af.$B$BDe bol van een magiër bevat grote kracht. Hij helpt ons om meer te ontdekken over deze ceremonie en over de magie die de Gordunni gebruiken.",
  o = "Rok Orhan in Camp Mojache wil dat je een Gordunni Orb vindt.",
  p = "We moeten meer te weten komen over waarom de Gordunni hier zijn, $N.",
  c = "Deze bol geeft ons meer informatie over de Gordunni... en die gebruiken we om hun ondergang te plannen, $N.",
  g = { {"duistere", "dark (duister)"}, {"ceremonie", "ceremony"}, {"voor zover", "as far as"}, {"ritueel", "ritual"}, {"magiërheren", "mage-lords (magiërheer)"}, {"bol", "orb, sphere"}, {"bevat", "contains (bevatten)"}, {"ondergang", "downfall"} },
},

[2742] = { en = "Rin'ji is Trapped!", tier = 4,
  t = "Rin'ji zit vast!",
  d = "Hé, $r!$B$BRin'ji is bijl kwijt en is gevangen! Alsjeblieft, help Rin'ji ontsnappen. Ik weet dat een $r zoals jij niet van Rin'ji's soort houdt, maar Rin'ji smeekt! Moet hier weg!$B$BRin'ji heeft iets voor aardige $r als $ghij Rin'ji hier weghelpt:zij Rin'ji hier weghelpt;...$B$BRin'ji heeft iets geheims verstopt bij de Overlook Cliffs.",
  o = "Begeleid Rin'ji de Quel'Danil Lodge uit en zoek daarna zijn verborgen geheim bij de Overlook Cliffs in het oosten.",
  p = "Rin'ji is bang!",
  c = "Deze trollentablet moet het \"geheim\" zijn waar Rin'ji het over had.$B$BHij staat vol vreemde tekens, en je kunt niet ontcijferen wat er op de tablet staat.",
  e = "Breng Rin'ji in veiligheid",
  g = { {"zit vast", "is trapped (vastzitten)"}, {"bijl", "axe"}, {"kwijt", "lost"}, {"gevangen", "captured (vangen)"}, {"ontsnappen", "to escape"}, {"smeekt", "begs (smeken)"}, {"weghelpt", "helps get away (weghelpen)"}, {"verstopt", "hidden (verstoppen)"}, {"begeleid", "escort (begeleiden)"}, {"verborgen", "hidden"}, {"trollentablet", "troll tablet"}, {"tekens", "markings, signs (teken)"}, {"ontcijferen", "to decipher"} },
},

[2782] = { en = "Rin'ji's Secret", tier = 4,
  t = "Rin'ji's geheim",
  d = "De tablet staat vol tekens van de Witherbark-trollen. Rin'ji's geheim is echt een raadsel...$B$BMisschien heb je hier iets heel waardevols in handen. Maar het tegenovergestelde kan ook. Een Witherbark-trol in nood zou waarschijnlijk alles doen om uit de problemen te komen...",
  o = "Oran Snakewrithe is een bekende geleerde als het om de Witherbark-trollen gaat. Misschien kan zij de tablet ontcijferen. Ze woont in de Magic Quarter van de Undercity.",
  p = "Zo, wat is dit nu?",
  c = "Deze tablet... Heel ongewoon... Waar heb je hem gevonden, $N?",
