[3002] = { en = "The Gordunni Orb", tier = 4,
  t = "De Gordunni-bol",
  d = "Ik ken mijn vijand goed, maar ik ben een krijger, $N. Ik heb geen idee wat deze bol allemaal kan.$B$BIk ken een magiër in Orgrimmar die ons meer over de bol kan vertellen. Breng hem naar hem toe.",
  o = "Breng de Gordunni Orb naar Uthel'nay in de Darkbriar Lodge in Orgrimmar.",
  p = "Wat heb je voor me meegebracht, $r?",
