},

[3123] = { en = "Testing the Vessel", tier = 4,
  t = "Het vat testen",
  d = "Dit wordt een test, van het ritueel dat ik heb uitgevoerd én van jouw vaardigheden. Neem dit vat, $N. Hiermee heb je de kracht om een wezen te laten krimpen en het erin te vangen.$B$BReis naar de Hinterlands en zoek de wezens die Wildkin heten. Ooit waren ze huisdieren van Elune, de godin van de nachtelfen. De vicious, primitive en savage owlbeasts zijn je doelwit, $N. Dood er 10 en gebruik het muisek-vat om ze te laten krimpen en te vangen, voordat hun geest kan ontsnappen.",
  o = "Reis naar de Hinterlands en zoek de Wildkin. Dood er 10 en gebruik het Muisek Vessel om de gevallen Wildkin te laten krimpen en te vangen.$B$BBreng 10 Wildkin Muiseks en het Muisek Vessel naar Witch Doctor Uzer'i in Feralas.",
  p = "Is het je gelukt om de wildkin te vangen?$B$BAls dat lukt, zijn we klaar om ook de muisek van de wezens van Feralas te laten krimpen en te vangen.",
  c = "Als een wezen een gewelddadige dood sterft, kan zijn muisek ontsnappen en wraak zoeken. Door de wezens te laten krimpen, zoals jij deed, $N, kan de muisek niet ontsnappen. Nu kunnen we hem gebruiken zoals we willen!",
  g = { {"vat", "vessel"}, {"uitgevoerd", "performed (uitvoeren)"}, {"vaardigheden", "abilities, skills (vaardigheid)"}, {"krimpen", "to shrink"}, {"godin", "goddess"}, {"doelwit", "target"}, {"geest", "spirit"}, {"ontsnappen", "to escape"}, {"gewelddadige", "violent (gewelddadig)"}, {"wraak", "revenge"} },
},

[3124] = { en = "Hippogryph Muisek", tier = 4,
  t = "Hippogrief-muisek",
  d = "Je hebt bewezen dat je te vertrouwen bent en dat je het muisek-vat kunt gebruiken. Daarom wil ik nu dat je een ander wezen vangt.$B$BHippogriefen zijn al vele jaren trouwe metgezellen van de nachtelfen. Hun geest is trouw en standvastig.$B$BJouw taak is om 10 frayfeather-hippogriefen te doden. Laat ze daarna snel krimpen en vang ze in het vat, zodat hun muisek bewaard blijft. Je vindt de hippogriefen in de High Wilderness, ten zuiden van hier.",
  o = "Dood 10 Frayfeather Hippogryphs van elk type en gebruik daarna het Muisek Vessel om ze te laten krimpen en te vangen.",
  p = "Is het je gelukt om de hippogriefen te vangen?",
  c = "Als we na het doden van een dier de muisek laten ontsnappen, kan die de vorm aannemen van een nog groter wezen. Dan zouden we nooit veilig zijn voor zijn wraak.$B$BIk heb je een gevaarlijke taak gegeven, $N. En weer heb je hem goed volbracht.",
  g = { {"bewezen", "proven (bewijzen)"}, {"te vertrouwen", "trustworthy"}, {"hippogriefen", "hippogryphs (hippogrief)"}, {"trouwe", "loyal (trouw)"}, {"metgezellen", "companions (metgezel)"}, {"standvastig", "steadfast"}, {"bewaard", "preserved, kept (bewaren)"}, {"vorm aannemen", "to take the form"}, {"wraak", "revenge, vengeance"}, {"volbracht", "completed (volbrengen)"} },
},

[7029] = { en = "Vyletongue Corruption", tier = 4,
  t = "Het verderf van Vyletongue",
  d = "Een sater die Vyletongue heet, heeft de grotten van Maraudon besmet. Daardoor groeien veel van de planten binnen niet meer goed.$B$BNeem dit flesje, $N. Vul het bij de oranje kristallen vijver in de grotten. Het laagje aan de binnenkant van het flesje werkt tegen de gifstoffen, zodat het water een genezend middel wordt.$B$BZoek de Vylestem-ranken in de oranje grotten en gebruik de gezuiverde vloeistof op ze. Het verderf wordt dan uit de plant verdreven. Maar weet wel dat Vyletongue de plant nog steeds beheerst. Misschien gebruikt hij hem tegen jou...",
  o = "Vul de Coated Cerulean Vial bij de oranje kristallen vijver in Maraudon.$B$BGebruik de Filled Cerulean Vial op de Vylestem Vines, zodat de besmette Noxxious Scion tevoorschijn moet komen.$B$BGenees 8 planten door deze Noxxious Scion te doden, en ga dan terug naar Vark Battlescar in Shadowprey Village.",
  p = "Als je de plant kunt genezen, gaat hij weer groeien. We moeten doen wat we kunnen, $N...",
  c = "Dank je dat je dit hebt teruggebracht, $N. Met de vloeistof die je nog voor me hebt meegebracht, kan ik mijn onderzoek voortzetten.$B$BEr is nog veel te doen, maar jij hebt een deel van het verderf genezen dat Vyletongue in Maraudon heeft verspreid. Neem dit aan, met mijn dank.",
  o1 = "Vylestem Vines genezen",
  g = { {"verderf", "corruption"}, {"sater", "satyr"}, {"grotten", "caverns, caves (grot)"}, {"besmet", "corrupted, infected (besmetten)"}, {"flesje", "vial, small bottle"}, {"vijver", "pool, pond"}, {"laagje", "coating, thin layer"}, {"gifstoffen", "toxins (gifstof)"}, {"genezend middel", "healing agent"}, {"ranken", "vines (rank)"}, {"gezuiverde", "purified (zuiveren)"}, {"vloeistof", "liquid"}, {"verdreven", "driven out, purged (verdrijven)"}, {"beheerst", "controls (beheersen)"}, {"voortzetten", "to continue"} },
},

[7731] = { en = "Stinglasher", tier = 4,
  t = "Stinglasher",
  d = "Toen we de Writhing Deep onderzochten, zag een van onze verkenners een reusachtig insect. Het was veel groter dan de andere insecten die we hebben gezien, en het zwierf rond over het grillige terrein. Het is niet alleen groter; het lijkt ook een soort aura af te scheiden die de andere insecten niet hebben. We hebben het een naam gegeven: Stinglasher.$B$BDe ingewanden van dit beest zijn ontzettend waardevol om te bestuderen, nu we zoeken naar de beste manier om deze nieuwe bedreiging aan te pakken. Snijd zijn klieren eruit en breng ze meteen naar mij!",
  o = "Versla Stinglasher in de Writhing Deep en breng zijn klieren naar Hadoken Swiftstrider in Camp Mojache, Feralas.",
  p = "Is het je al gelukt om Stinglasher te verslaan?",
  c = "Indrukwekkend, $c... heel indrukwekkend! Als Stinglasher echt een van hun sterkste wezens is, zal het onderzoek naar dit beest op den duur heel waardevol blijken. Het is nu mijn taak om ervoor te zorgen dat we ons lang genoeg verdedigen om er ons voordeel mee te doen.$B$BAanvaard alsjeblieft deze beloning in munten, als teken van dank van het hele kamp, $N. Goed gedaan.",
  g = { {"reusachtig", "giant, huge"}, {"zwierf", "wandered (zwerven)"}, {"grillige", "twisted, irregular (grillig)"}, {"terrein", "terrain"}, {"af te scheiden", "to secrete (afscheiden)"}, {"ingewanden", "innards, guts"}, {"bestuderen", "to study"}, {"klieren", "glands (klier)"}, {"indrukwekkend", "impressive"}, {"op den duur", "in time, in the long run"}, {"verdedigen", "to defend"}, {"voordeel", "advantage"}, {"aanvaard", "accept (aanvaarden)"}, {"beloning", "reward, bounty"} },
},

[8273] = { en = "Oran's Gratitude", tier = 4,
  t = "Orans dankbaarheid",
  c = "Nou, is dat niet interessant? Je zegt dat je deze tablet op een klein, verlaten eiland bij The Overlook Cliffs in The Hinterlands hebt gevonden, $c? Heel interessant, inderdaad. <Oran legt de tablet voorzichtig weg en wrijft in haar handen.>$B$BIk dank je voor je moeite. Onze Dark Lady zal heel blij zijn met deze ontdekking. Hier, laat me je beloning geven die bij je werk past.",
  g = { {"dankbaarheid", "gratitude"}, {"verlaten", "deserted"}, {"eiland", "island"}, {"inderdaad", "indeed"}, {"voorzichtig", "carefully"}, {"wrijft in haar handen", "rubs her hands together (wrijven)"}, {"moeite", "effort, trouble"}, {"ontdekking", "discovery"}, {"beloning", "reward"} },
},

[7732] = { en = "Zukk'ash Report", tier = 4,
  t = "Zukk'ash-rapport",
  d = "Je hebt de bedreiging van de Zukk'ash-insecten voor Camp Mojache dubbel zo goed aangepakt. Toch is het gevaar nog lang niet voorbij. Ik wil je nog één laatste taak vragen, namens de Horde.$B$BDit document bevat alle informatie die we over deze Zukk'ash-insecten hebben verzameld. Breng het naar Zilzibin Drumlore in de Drag van Orgrimmar. Hij is een expert in vreemde wezens zoals deze. Ik hoop dat hij iets kan met de kennis die we hebben verkregen.",
  o = "Breng het Camp Mojache Zukk'ash Report naar Zilzibin Drumlore. Hij woont in de Drag van Orgrimmar.",
  p = "Gegroet, vriend... je ziet eruit alsof je met een dringende zaak bezig bent. Kan ik je ergens mee helpen?",
  c = "Ah, dit had ik al verwacht. Deze wezens die je hebt bevochten... zij zijn een oude bedreiging die de Horde steeds weer negeert. Hadoken heeft er goed aan gedaan om dit, en jou, naar mij te sturen.$B$BDe Zukk'ash zijn niets anders dan wezens die silithid heten. Sommigen denken dat ze alleen hersenloze plaaggeesten zijn. Maar geloof me: ze zijn een veel, veel grotere bedreiging dan alles wat de Alliance kan verzamelen.$B$BAls je wilt en sterk genoeg bent, kan ik je hulp goed gebruiken om dit gevaar aan het licht te brengen.",
  g = { {"aangepakt", "dealt with (aanpakken)"}, {"namens", "on behalf of"}, {"verzameld", "gathered (verzamelen)"}, {"kennis", "knowledge, lore"}, {"verkregen", "obtained (verkrijgen)"}, {"gegroet", "greetings"}, {"dringende", "urgent (dringend)"}, {"bevochten", "fought (bevechten)"}, {"negeert", "ignores (negeren)"}, {"hersenloze", "mindless (hersenloos)"}, {"plaaggeesten", "nuisances, pests (plaaggeest)"}, {"aan het licht brengen", "to bring to light"} },
},

[7734] = { en = "Improved Quality", tier = 4,
  t = "Betere kwaliteit",
  d = "Ik weet een nog BETERE bron van huiden, als je dat al kunt geloven! In het noorden van Feralas, diep in Rage Scar Hold, leeft nog een grote groep yeti's. Ze zijn veel sterker dan die waar je eerder mee te maken had. Dus als je zin hebt in een grotere uitdaging, moet je goed opletten!$B$BVoor een stapel van tien van hun huiden beloon ik je royaal. Breng ze hier naar mij toe, dan ronden we onze zaak af.",
  o = "Breng 10 Rage Scar Yeti Hides naar Jangdor Swiftstrider in Camp Mojache, Feralas.",
  p = "Als deze huiden van de Rage Scar-yeti's net zo goed zijn als die van hun Feral Scar-soortgenoten, dan zijn ze misschien wel zo sterk als thorium!$B$BStel je voor!",
  c = "Uitstekend, uitstekend! Hier ga ik ongelooflijk goed mee kunnen werken. Ik zie nu al dat ze na een goede behandeling veel harder worden.$B$BNogmaals bedankt voor je hulp, $N. Hier, neem een van mijn nieuwste creaties.",
  g = { {"bron", "source"}, {"te maken had", "dealt with (te maken hebben met)"}, {"uitdaging", "challenge"}, {"opletten", "to watch out, pay attention"}, {"royaal", "generously, handsomely"}, {"ronden af", "finish, round off (afronden)"}, {"soortgenoten", "counterparts, own kind (soortgenoot)"}, {"stel je voor", "imagine (zich voorstellen)"}, {"ongelooflijk", "incredibly"}, {"nogmaals", "once again"}, {"creaties", "creations (creatie)"} },
},

[7738] = { en = "Perfect Yeti Hide", tier = 4,
  t = "Perfecte yetihuid",
  d = "Je hebt iets gevonden dat best eens een perfecte yetihuid kan zijn. Je ziet meteen dat hij uitzonderlijk dik en stevig is, zelfs meer dan de huiden van de yeti's in Rage Scar.$B$BJangdor Swiftstrider in Camp Mojache is op zoek naar yetihuiden. Deze huid kan dus heel interessant voor hem zijn.",
  o = "Breng de Perfect Yeti Hide naar Jangdor Swiftstrider in Camp Mojache, Feralas.",
  p = "Wat is dit, $N? Heb je iets bijzonders voor me?",
  c = "Dit is een ongelooflijke vondst! Volgens mij is dit de mooiste yetihuid die ik ooit heb gezien!$B$BDit verdient zeker een passende beloning. Normaal betaal ik niet zoveel voor één huid, maar ik weet zeker dat ik er iets bijzonders van kan maken. Bedankt dat je aan mij hebt gedacht, $N!",
  g = { {"best eens", "may very well"}, {"uitzonderlijk", "exceptionally"}, {"stevig", "sturdy, solid"}, {"op zoek naar", "looking for"}, {"vondst", "find, discovery"}, {"verdient", "deserves (verdienen)"}, {"passende", "fitting, appropriate (passend)"}, {"beloning", "reward"} },
},

[3062] = { en = "Dark Heart", tier = 4,
  t = "Duister hart",
  d = "Edana Hatetalon is de koningin van de Northspring-harpijen, die in de ruïnes in het westen wonen. Ze is door en door slecht; ik heb gehoord dat haar hart van kristal is. Ze voelt niets, behalve de haat die ze tegenover alle anderen voelt. Je moet het opnemen tegen Edana en me haar duistere hart brengen.$B$BIk heb gehoord dat harpijen een hoorn bij zich hebben. Als je erop blaast bij de Hatetalon-stenen, in het noorden van de ruïnes, roept dat de koningin op.$B$BStel je haar verbazing voor als niet haar eigen soort haar roept, maar haar dood.",
  o = "Talo Thornhoof in Camp Mojache wil Edana Hatetalon's Dark Heart hebben.",
  p = "De haat die Edana over het land verspreidt, moet worden gestopt.",
  c = "Nu weet ik dat Edana echt dood is. Dit hart bewaar ik, ter herinnering aan wat je hier voor mij hebt gedaan, $N. Dank je.",
  g = { {"harpijen", "harpies (harpij)"}, {"ruïnes", "ruins (ruïne)"}, {"door en door", "through and through"}, {"kristal", "crystal"}, {"haat", "hatred"}, {"het opnemen tegen", "to take on, face"}, {"hoorn", "horn"}, {"roept op", "summons (oproepen)"}, {"verbazing", "surprise, astonishment"}, {"soort", "kind, kin"}, {"verspreidt", "spreads (verspreiden)"}, {"ter herinnering aan", "in memory of"} },
},

[3063] = { en = "Vengeance on the Northspring", tier = 4,
  t = "Wraak op de Northspring",
  d = "Vroeger was ik een ervaren jager. Ik was voor geen enkel wezen in de buurt bang. Tot...$B$BIk zat in het bos mijn zwaard te slijpen na een zwaar gevecht, toen ik werd overvallen. Harpijen omsingelden me, en ik wist me maar net in veiligheid te slepen.$B$BZelfs nu hoor ik hun kreten nog steeds echoën...$B$BNa die dag ben ik nooit meer dezelfde geweest. Maar de haat kookt in me. Ik moet ze terugpakken, na al die jaren.$B$BJe vindt de Northspring-harpijen ten westen van hier. $N, neem wraak voor mij.",
  o = "Talo Thornhoof wil dat je 4 Northspring Harpies, 4 Northspring Roguefeathers, 4 Northspring Windcallers en 4 Northspring Slayers doodt.",
  p = "De vleugels van de Northspring-harpijen zijn zo zwart als de nacht. Houd je ogen op ze gericht, anders verdwijnen ze in het donker.",
  c = "Dank je, $N. Je hebt de geest van een oude tauren rust gegeven.",
  g = { {"ervaren", "experienced, seasoned"}, {"te slijpen", "to sharpen (slijpen)"}, {"overvallen", "ambushed, attacked (overvallen)"}, {"omsingelden", "surrounded (omsingelen)"}, {"maar net", "barely, only just"}, {"slepen", "to drag"}, {"kreten", "cries (kreet)"}, {"echoën", "to echo"}, {"kookt", "boils (koken)"}, {"terugpakken", "to get even, pay back"}, {"wraak nemen", "to take revenge"}, {"gericht", "aimed, fixed (richten)"} },
},

[3126] = { en = "Treant Muisek", tier = 4,
  t = "Treant-muisek",
  d = "De wandering forest walkers die door het bos zwerven, zijn ons volgende doel, $N. De nachtelfen hebben treants als bondgenoten ingezet om tegen de Horde te vechten. Ze bewegen misschien langzaam, maar als beschermers zijn ze onmiskenbaar belangrijk.$B$BBinnenkort kunnen we deze kracht in ons eigen voordeel gebruiken.$B$BZoek 3 wandering forest walkers. Dood ze en gebruik het muisek-vat om ze te laten krimpen en te vangen.",
  o = "Dood 3 Wandering Forest Walkers. Gebruik het Muisek Vessel om de gevallen Treants te laten krimpen en te vangen.",
  p = "Is het je gelukt om de wandering forest walkers te vangen?",
  c = "Dank je, $N. Onze verzameling muisek is bijna compleet.",
  g = { {"zwerven", "to wander, roam"}, {"doel", "target, goal"}, {"bondgenoten", "allies (bondgenoot)"}, {"ingezet", "enlisted, deployed (inzetten)"}, {"beschermers", "protectors (beschermer)"}, {"onmiskenbaar", "undeniably"}, {"voordeel", "benefit, advantage"}, {"verzameling", "collection"} },
},

[3127] = { en = "Mountain Giant Muisek", tier = 4,
  t = "Berggigant-muisek",
  d = "De laatste taak die ik van je vraag, is om naar het noordwesten te reizen en de laatste vijand te vinden.$B$BDe berggiganten verlieten de bergen om de nachtelfen te helpen, toen het Burning Legion in de wereld verscheen. Je herkent ze aan hun enorme grootte, en aan de manier waarop de grond begint te trillen als je over hun rotsige terrein reist.$B$BIk kan niet wachten om kracht van die omvang te benutten. Dood 7 berggiganten en gebruik dan het muisek-vat om hun krachtige muisek te vangen.",
  o = "Dood 7 Land Walkers of Cliff Giants. Gebruik het Muisek Vessel om de gevallen Mountain Giants te laten krimpen en te vangen.",
  p = "Is het je gelukt om de berggiganten te vangen?",
  c = "Stel je eens voor wat we nu allemaal kunnen met wat we bezitten, $N. Samen met de materialen die je hebt verzameld, kan ik de muisek van deze wezens voor altijd opsluiten in alles wat ik maar wil.",
  g = { {"berggiganten", "mountain giants (berggigant)"}, {"verlieten", "left (verlaten)"}, {"verscheen", "appeared (verschijnen)"}, {"herkent", "recognize (herkennen)"}, {"enorme", "massive, enormous (enorm)"}, {"trillen", "to shake, tremble"}, {"rotsige", "rocky (rotsig)"}, {"omvang", "size, scale"}, {"benutten", "to harness, make use of"}, {"bezitten", "to possess"}, {"opsluiten", "to lock up, trap"} },
},

[3128] = { en = "Natural Materials", tier = 4,
  t = "Natuurlijke materialen",
  d = "Ik heb bepaalde materialen nodig om mijn werk af te maken... Je kunt dit doen naast de andere taken die ik je geef.$B$BIk heb een versplinterd blok hout nodig van een treant uit Feralas. Dan korstige mineralen; die vind je op de berggiganten en de feeëndraken in het westen. Zoek ook wat taaie pezen van de owlbeasts uit de Hinterlands of de hippogriefen uit Feralas. Tot slot heb ik een grote hoeveelheid metalen scherven nodig van een van de wezens die ik heb genoemd.",
  o = "Breng 2 Splintered Logs, 6 Encrusted Minerals, 20 stukken Resilient Sinew en 40 Metallic Fragments naar Witch Doctor Uzer'i in Camp Mojache.",
  p = "Is het je gelukt om de materialen te verzamelen die ik nodig heb?",
  c = "Uitstekend! Samen met de muisek moeten deze materialen precies het resultaat geven waar we op hoopten.",
  g = { {"bepaalde", "certain (bepaald)"}, {"af te maken", "to finish, complete (afmaken)"}, {"versplinterd", "splintered"}, {"blok hout", "log"}, {"korstige", "encrusted, crusty (korstig)"}, {"mineralen", "minerals (mineraal)"}, {"feeëndraken", "faerie dragons (feeëndraak)"}, {"taaie", "tough, resilient (taai)"}, {"pezen", "sinews (pees)"}, {"hoeveelheid", "amount"}, {"scherven", "fragments, shards (scherf)"}, {"genoemd", "mentioned (noemen)"} },
},

[3129] = { en = "Weapons of Spirit", tier = 4,
  t = "Wapens van de geest",
  d = "Het is een moeilijk proces om de muisek in de wapens te laten trekken. Nu heb ik alle nodige materialen en de muisek van de wezens die je hebt gevangen, dus ik kan beginnen. Wacht even; ik ben zo terug.",
  o = "Witch Doctor Uzer'i wil dat je even wacht terwijl hij de wapens klaarmaakt.",
  c = "Zoals beloofd mag je kiezen, $N. De muisek van de wezens is voor altijd verzegeld in de kracht van deze wapens.$B$BJe kunt hun energie nu gebruiken als je eigen energie. Gebruik hem goed.",
  g = { {"proces", "process"}, {"laten trekken", "to let soak in, imbue"}, {"nodige", "required (nodig)"}, {"gevangen", "captured (vangen)"}, {"klaarmaakt", "prepares (klaarmaken)"}, {"beloofd", "promised (beloven)"}, {"verzegeld", "sealed (verzegelen)"} },
},

[7064] = { en = "Corruption of Earth and Seed", tier = 4,
  t = "Verderf van aarde en zaad",
  d = "Diep in Maraudon leeft een kwaadaardig wezen van chaos: Princess Theradras. Zij is een elementaire kracht van de aarde, verwant aan de Old Gods. Lang geleden kregen zij en Zaetar, de eerste zoon van Cenarius, een relatie. Hun nakomelingen werden bij de volkeren van Kalimdor bekend als de centauren. Als dank, zo ondankbaar als ze zijn, hebben de centauren Zaetar gedood, en nu houden ze zijn overblijfselen in bezit. Mijn opdracht hier is om mensen te vinden die sterk genoeg zijn om Theradras te verslaan. Dan kunnen wij de overblijfselen van Zaetar terughalen, voordat we teruggaan naar Stonetalon.",
  o = "Versla Princess Theradras en ga terug naar Selendra bij Shadowprey Village in Desolace.",
  p = "Ik zou deze strijd liever zelf voeren, maar we hebben geen andere keus. We hebben sterkere strijders nodig, en de volkeren van Azeroth hebben zonder enige twijfel bewezen dat ze zulke dingen kunnen overwinnen als ze samenwerken. Daarom vragen we jou om hulp.$B$BIk hoop alleen dat het genoeg is.$B$BZaetar, de broer van Remulos, heeft deze wereld veel pijn gebracht, en uiteindelijk leidde dat tot zijn eigen dood. Ik hoop alleen dat ik niet nog meer doden heb veroorzaakt door jou om hulp te vragen.",
  c = "Dit is geweldig nieuws, $N! Dank je!$B$BIk ga met Marandis praten en hem om raad vragen over de overblijfselen van Zaetar. Maar jij hebt in elk geval de moeilijkste taak volbracht.$B$BMe is verteld dat ik, als onze missie zou slagen, de mensen die ons hielpen mocht belonen. Ik heb deze voorwerpen gekregen als geschenken van ons volk. Je mag er één kiezen.",
  g = { {"kwaadaardig", "evil, malicious"}, {"elementaire", "elemental (elementair)"}, {"verwant aan", "related to"}, {"nakomelingen", "offspring (nakomeling)"}, {"ondankbaar", "ungrateful"}, {"overblijfselen", "remains (overblijfsel)"}, {"in bezit", "in possession"}, {"terughalen", "to recover, bring back"}, {"voeren", "to wage, fight (a battle)"}, {"zonder enige twijfel", "without a doubt"}, {"overwinnen", "to overcome"}, {"veroorzaakt", "caused (veroorzaken)"}, {"om raad vragen", "to ask for advice"}, {"slagen", "to succeed"}, {"geschenken", "gifts, tokens (geschenk)"} },
},

[4120] = { en = "The Strength of Corruption", tier = 4,
  t = "De kracht van verderf",
  d = "Als jager probeer ik de sterke kanten van mijn tegenstanders na te doen. Je kunt een gevecht in je voordeel laten keren door je vijand gewoon goed te kennen, $N.$B$BIn een gebied dat Felwood heet, ten noorden van Ashenvale, zijn de wezens besmet door een stof die fel heet. De beren en wolven zijn er gek van geworden, maar ik denk dat ze er ook nog sterker door zijn geworden.$B$BGa, $N. Reis naar Felwood en neem het op tegen deze beesten. Ontdek zelf of ze echt zo sterk zijn als ik denk.",
  o = "Talo Thornhoof in Camp Mojache in Feralas wil dat je 12 Angerclaw Grizzlies en 12 Felpaw Ravagers doodt in Felwood.",
  p = "Alles wat door de fel is aangeraakt, geeft een vreemde groene gloed af... Ik voel dat het kwaad is, maar tegelijk ook heel krachtig.",
  c = "Zo te horen tonen de wezens een hersenloze woestheid...$b$bBlijf op je hoede, $N. Het is in je eigen belang om meer over het verderf te leren. Ken altijd je vijand.",
  g = { {"verderf", "corruption"}, {"na te doen", "to imitate, emulate (nadoen)"}, {"tegenstanders", "opponents (tegenstander)"}, {"laten keren", "to turn (keren)"}, {"besmet", "tainted, infected (besmetten)"}, {"stof", "substance"}, {"neem het op tegen", "face, take on (het opnemen tegen)"}, {"gloed", "glow"}, {"tegelijk", "at the same time"}, {"hersenloze", "mindless (hersenloos)"}, {"woestheid", "ferocity"}, {"op je hoede", "on your guard, alert"}, {"belang", "interest"} },
},

})

